<?php use App\Support\Ui; ?>
<div class="page-heading"><div><span class="eyebrow">OPERATIONS DIRECTORY</span><h1>Interviews</h1><p>Search and filter the complete booking record.</p></div><a class="button primary" href="<?= $e($url('admin/interview/new')) ?>"><?= Ui::icon('plus') ?>New interview</a></div>
<form class="filter-bar interview-filters card" method="get"><div class="field filter-search"><label for="search">Search</label><input id="search" name="search" value="<?= $e($filters['search']??'') ?>" placeholder="Candidate, phone, company, role"></div><div class="field"><label for="date_from">From</label><input type="date" id="date_from" name="date_from" value="<?= $e($filters['date_from']??'') ?>"></div><div class="field"><label for="date_to">To</label><input type="date" id="date_to" name="date_to" value="<?= $e($filters['date_to']??'') ?>"></div><div class="field"><label for="type">Type</label><select id="type" name="type"><option value="">All</option><option value="TOOL" <?= ($filters['type']??'')==='TOOL'?'selected':'' ?>>Tool</option><option value="NORMAL" <?= ($filters['type']??'')==='NORMAL'?'selected':'' ?>>Normal</option></select></div><div class="field"><label for="technology_id">Technology</label><select id="technology_id" name="technology_id"><option value="">All</option><?php foreach($technologies as $x):?><option value="<?= $e($x['id']) ?>" <?= ($filters['technology_id']??'')==(string)$x['id']?'selected':'' ?>><?= $e($x['name']) ?></option><?php endforeach;?></select></div><div class="field"><label for="support_person_id">Support</label><select id="support_person_id" name="support_person_id"><option value="">All</option><?php foreach($supportPeople as $x):?><option value="<?= $e($x['id']) ?>" <?= ($filters['support_person_id']??'')==(string)$x['id']?'selected':'' ?>><?= $e($x['name']) ?></option><?php endforeach;?></select></div><div class="field"><label for="resource_id">Resource</label><select id="resource_id" name="resource_id"><option value="">All</option><?php foreach($resources as $x):?><option value="<?= $e($x['id']) ?>" <?= ($filters['resource_id']??'')==(string)$x['id']?'selected':'' ?>><?= $e($x['name']) ?></option><?php endforeach;?></select></div><button class="button primary">Apply</button><a class="button secondary" href="<?= $e($url('admin/interviews')) ?>">Clear</a></form>
<section class="card admin-interview-table"><div class="card-heading"><div><h2>Booking records</h2><p><?= $e($pagination['total']) ?> result<?= $pagination['total']===1?'':'s' ?> · Asia/Kolkata</p></div></div><?php if(!$interviews):?><div class="empty-state"><h3>No interviews match these filters.</h3><p>Adjust the date range or clear a filter.</p></div><?php else:?><div class="table-scroll desktop-record-table"><table><thead><tr><th>Candidate & company</th><th>Date & time</th><th>Technology</th><th>Type</th><th>Resource</th><th>Support</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($interviews as $i):?><tr><td><span class="table-primary"><?= $e($i['candidate_name']) ?><?php if($i['candidate_deleted']):?><span class="deleted-label">Deleted candidate</span><?php endif;?></span><span class="table-secondary"><?= $i['candidate_phone']?$e($i['candidate_phone']).' · ':'' ?><?= $e($i['company_name']) ?></span></td><td><span class="table-primary"><?= $e($i['start_local']->format('d M Y')) ?></span><span class="table-secondary"><?= $e($i['display_time']) ?></span></td><td><?= $e($i['technology_name']) ?></td><td><span class="badge <?= $i['interview_type']==='TOOL'?'purple':'neutral' ?>"><?= $e(ucfirst(strtolower($i['interview_type']))) ?></span></td><td><?= $e($i['resource_name']) ?></td><td><?= $e($i['support_person_name']??'—') ?></td><td><span class="badge <?= $i['status']==='BOOKED'?'green':'danger-badge' ?>"><?= $e(ucfirst(strtolower($i['status']))) ?></span></td><td><a class="row-link" aria-label="Open booking" href="<?= $e($url('admin/interview?id='.$i['id'])) ?>"><?= Ui::icon('chevron') ?></a></td></tr><?php endforeach;?></tbody></table></div>
<div class="mobile-record-list interview-mobile-list"><?php foreach($interviews as $i):?><a class="mobile-record-card" href="<?= $e($url('admin/interview?id='.$i['id'])) ?>"><div class="mobile-record-head"><div><time><?= $e($i['start_local']->format('d M Y')) ?> · <?= $e($i['display_time']) ?></time><h3><?= $e($i['candidate_name']) ?></h3></div><span class="badge <?= $i['status']==='BOOKED'?'green':'danger-badge' ?>"><?= $e(ucfirst(strtolower($i['status']))) ?></span></div><p><?= $e($i['company_name']) ?> · <?= $e($i['job_role']) ?></p><?php if($i['candidate_deleted']):?><span class="deleted-label">Deleted candidate</span><?php endif;?><dl class="mobile-record-meta"><div><dt>Technology</dt><dd><?= $e($i['technology_name']) ?></dd></div><div><dt>Type</dt><dd><?= $e(ucfirst(strtolower($i['interview_type']))) ?></dd></div><div><dt>Resource</dt><dd><?= $e($i['resource_name']) ?></dd></div><div><dt>Support</dt><dd><?= $e($i['support_person_name']??'Not required') ?></dd></div></dl><span class="mobile-record-action">View details <?= Ui::icon('chevron') ?></span></a><?php endforeach;?></div><?php endif;?></section>
<?php if($pagination['pages']>1):?><nav class="pagination" aria-label="Interview pages"><?php for($p=1;$p<=$pagination['pages'];$p++):?><a class="<?= $p===$pagination['page']?'active':'' ?>" href="?<?= $e(http_build_query($filters+['page'=>$p])) ?>"><?= $p ?></a><?php endfor;?></nav><?php endif;?>
